readme=readme_path.read_text(encoding='utf-8')
anchor='''- This containment removes the identified `Distance` package from the private Python dependency graph. It is not a legal opinion or overall release-clearance claim; FFmpeg, VB-CABLE, and remaining third-party notices retain their separate gates.\n'''
addition='''\n### Exceptional Frozen-Wheel License Material\n\nThe R3 full Windows staging proof established that 106 of the 116 frozen production distributions carry their own license/notice material after installation. Ten exact distributions do not. The release must **not** weaken `generate_third_party_notices.mjs` or allow those packages to pass without material. Instead, staging must add the reviewed upstream material below into that package's own `.dist-info/licenses/` directory, together with `TRANSLATEIT_SOURCE.txt` recording the exact source authority.\n\n```text\nctranslate2==4.8.1\n  source tag v4.8.1 -> commit 0d8bcd362ac75ef860ef161d6f0efad0ae439ff0\n  LICENSE sha256 54aa79d9fe3c09e67a16dcd95b9e88676405a6ec174efda31036983cf7672ecb\n\nflatbuffers==25.12.19\n  source tag v25.12.19 -> commit 7e163021e59cca4f8e1e35a7c828b5c6b7915953\n  LICENSE sha256 cfc7749b96f63bd31c3c42b5c471bf756814053e847c10f3eb003417bc523d30\n\njieba==0.42.1\n  PyPI sdist sha256 055ca12f62674fafed09427f176506079bc135638a14e23e25be909131928db2\n  source tag v0.42.1 -> commit 1e20c89b66f56c9301b0feed211733ffaa1bd72a\n  LICENSE sha256 18ba0984839f85853b29fadaf992f7dba8fd0ca0fbeae34de2b8735222dc7a37\n\njieba-fast==0.53\n  PyPI sdist sha256 e92089d52faa91d51b6a7c1e6e4c4c85064a0e36f6a29257af2254b9e558ddd0\n  upstream has no release tag; supplemental LICENSE is pinned to repository commit 5e6b21dece184e1004a35bfd802c8772059de3ab\n  LICENSE sha256 18ba0984839f85853b29fadaf992f7dba8fd0ca0fbeae34de2b8735222dc7a37\n\nloguru==0.7.3\n  PyPI sdist sha256 19480589e77d47b8d85b2c827ad95d49bf31b0dcde16593892eb51dd18706eb6\n  source tag 0.7.3 -> commit ae3bfd1b85b6b4a3db535f69b975687c79498be4\n  LICENSE sha256 b35d026cc7aca9d5859a02eb87ddf7a386a24c986838651bd1f283f94e003327\n\nonnxruntime==1.28.0\n  source tag v1.28.0 -> commit da9b5e364c465de65c49d91e696cd6485270757f\n  LICENSE sha256 2f07c72751aed99790b8a4869cf2311df85a860b22ded05fa22803587a48922c\n  ThirdPartyNotices.txt sha256 0e07b95f3a8d6230037707c5c4a2b554d12c4cb67369669ac255635528ffcee2\n\nsentencepiece==0.2.2\n  PyPI sdist sha256 3d2b5e824b5622038dc7b490897efe05ebbbb9e7350fc142f3ecc8789ef9bdf6\n  package LICENSE sha256 cfc7749b96f63bd31c3c42b5c471bf756814053e847c10f3eb003417bc523d30\n  bundled abseil-cpp LICENSE sha256 c79a7fea0e3cac04cd43f20e7b648e5a0ff8fa5344e644b0ee09ca1162b62747\n  bundled darts_clone LICENSE sha256 155f59997298ee336602c49f9c1110f268ac394ca2197eb02647a3555935ad52\n  bundled esaxx LICENSE sha256 7c28553d1d3312d65fe309f76a22ebaf33a3d76c8c1e3b98a88ee4654ecb53db\n  bundled protobuf-lite LICENSE sha256 6e5e117324afd944dcf67f36cf329843bc1a92229a8cd9bb573d7a83130fea7d\n\ntensorboard-data-server==0.7.2\n  exact upstream release commit 81150b898a306b89cde90e949358c2eefe018eaa (`tensorboard-data-server 0.7.2`)\n  root LICENSE sha256 d7c9068d896188264b60827b8cd1e25fdb9f5b5cad0b1589e90b96c87729c404\n\ntokenizers==0.21.4\n  PyPI sdist sha256 fa23f85fbc9a02ec5c6978da172cdcbac23498c3ca9f3645c5c68740ac007880\n  package LICENSE sha256 c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4\n\nwordsegment==1.3.1\n  PyPI sdist sha256 3dcc7cd1e9bba3f3ffe6a0e54d98377bc502fc34e9e9d8c8199ac5636924f023\n  LICENSE sha256 8fe4d37c518608a57c6b0f24e26915144f8daf460eb4e1572146596ec3673294\n```\n\nThese are staging inputs, not network actions performed by the installed application or by `build_release.ps1`. The release payload validator pins the exact added files/hashes and their source records. Any version change, source-revision drift, or replacement wheel must be re-audited instead of silently reusing this exception list.\n'''
if anchor not in readme: raise SystemExit('LocalWorker exception anchor missing')
if '### Exceptional Frozen-Wheel License Material' not in readme:
    readme=readme.replace(anchor,anchor+addition,1)
readme_path.write_text(readme,encoding='utf-8')

validator=validator_path.read_text(encoding='utf-8')
anchor='''const expectedVbCableFiles = {\n'''
constant='''const exceptionalPythonLicenseMaterials = {\n  "ctranslate2-4.8.1.dist-info": {\n    source: ["package=ctranslate2==4.8.1", "source_repo=OpenNMT/CTranslate2", "source_ref=v4.8.1", "source_commit=0d8bcd362ac75ef860ef161d6f0efad0ae439ff0"],\n    files: { "LICENSE": "54aa79d9fe3c09e67a16dcd95b9e88676405a6ec174efda31036983cf7672ecb" },\n  },\n  "flatbuffers-25.12.19.dist-info": {\n    source: ["package=flatbuffers==25.12.19", "source_repo=google/flatbuffers", "source_ref=v25.12.19", "source_commit=7e163021e59cca4f8e1e35a7c828b5c6b7915953"],\n    files: { "LICENSE": "cfc7749b96f63bd31c3c42b5c471bf756814053e847c10f3eb003417bc523d30" },\n  },\n  "jieba-0.42.1.dist-info": {\n    source: ["package=jieba==0.42.1", "sdist_sha256=055ca12f62674fafed09427f176506079bc135638a14e23e25be909131928db2", "source_repo=fxsjy/jieba", "source_ref=v0.42.1", "source_commit=1e20c89b66f56c9301b0feed211733ffaa1bd72a"],\n    files: { "LICENSE": "18ba0984839f85853b29fadaf992f7dba8fd0ca0fbeae34de2b8735222dc7a37" },\n  },\n  "jieba_fast-0.53.dist-info": {\n    source: ["package=jieba-fast==0.53", "sdist_sha256=e92089d52faa91d51b6a7c1e6e4c4c85064a0e36f6a29257af2254b9e558ddd0", "source_repo=deepcs233/jieba_fast", "source_commit=5e6b21dece184e1004a35bfd802c8772059de3ab", "upstream_release_tag=none"],\n    files: { "LICENSE": "18ba0984839f85853b29fadaf992f7dba8fd0ca0fbeae34de2b8735222dc7a37" },\n  },\n  "loguru-0.7.3.dist-info": {\n    source: ["package=loguru==0.7.3", "sdist_sha256=19480589e77d47b8d85b2c827ad95d49bf31b0dcde16593892eb51dd18706eb6", "source_repo=Delgan/loguru", "source_ref=0.7.3", "source_commit=ae3bfd1b85b6b4a3db535f69b975687c79498be4"],\n    files: { "LICENSE": "b35d026cc7aca9d5859a02eb87ddf7a386a24c986838651bd1f283f94e003327" },\n  },\n  "onnxruntime-1.28.0.dist-info": {\n    source: ["package=onnxruntime==1.28.0", "source_repo=microsoft/onnxruntime", "source_ref=v1.28.0", "source_commit=da9b5e364c465de65c49d91e696cd6485270757f"],\n    files: {\n      "LICENSE": "2f07c72751aed99790b8a4869cf2311df85a860b22ded05fa22803587a48922c",\n      "ThirdPartyNotices.txt": "0e07b95f3a8d6230037707c5c4a2b554d12c4cb67369669ac255635528ffcee2",\n    },\n  },\n  "sentencepiece-0.2.2.dist-info": {\n    source: ["package=sentencepiece==0.2.2", "sdist_sha256=3d2b5e824b5622038dc7b490897efe05ebbbb9e7350fc142f3ecc8789ef9bdf6"],\n    files: {\n      "LICENSE": "cfc7749b96f63bd31c3c42b5c471bf756814053e847c10f3eb003417bc523d30",\n      "ABSEIL_LICENSE": "c79a7fea0e3cac04cd43f20e7b648e5a0ff8fa5344e644b0ee09ca1162b62747",\n      "DARTS_CLONE_LICENSE": "155f59997298ee336602c49f9c1110f268ac394ca2197eb02647a3555935ad52",\n      "ESAXX_LICENSE": "7c28553d1d3312d65fe309f76a22ebaf33a3d76c8c1e3b98a88ee4654ecb53db",\n      "PROTOBUF_LITE_LICENSE": "6e5e117324afd944dcf67f36cf329843bc1a92229a8cd9bb573d7a83130fea7d",\n    },\n  },\n  "tensorboard_data_server-0.7.2.dist-info": {\n    source: ["package=tensorboard-data-server==0.7.2", "source_repo=tensorflow/tensorboard", "source_commit=81150b898a306b89cde90e949358c2eefe018eaa", "source_commit_message=tensorboard-data-server 0.7.2"],\n    files: { "LICENSE": "d7c9068d896188264b60827b8cd1e25fdb9f5b5cad0b1589e90b96c87729c404" },\n  },\n  "tokenizers-0.21.4.dist-info": {\n    source: ["package=tokenizers==0.21.4", "sdist_sha256=fa23f85fbc9a02ec5c6978da172cdcbac23498c3ca9f3645c5c68740ac007880"],\n    files: { "LICENSE": "c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4" },\n  },\n  "wordsegment-1.3.1.dist-info": {\n    source: ["package=wordsegment==1.3.1", "sdist_sha256=3dcc7cd1e9bba3f3ffe6a0e54d98377bc502fc34e9e9d8c8199ac5636924f023"],\n    files: { "LICENSE": "8fe4d37c518608a57c6b0f24e26915144f8daf460eb4e1572146596ec3673294" },\n  },\n};\n\n'''
if anchor not in validator: raise SystemExit('validator constant anchor missing')
if 'const exceptionalPythonLicenseMaterials' not in validator:
    validator=validator.replace(anchor,constant+anchor,1)

anchor='''const noticeBundlePath = thirdPartyNoticeOutputPath(backendRoot);\n'''
check='''for (const [distInfoName, requirement] of Object.entries(exceptionalPythonLicenseMaterials)) {\n  const distInfoRoot = join(pythonRoot, distInfoName);\n  const licensesRoot = join(distInfoRoot, "licenses");\n  requireDir(distInfoRoot, `LocalWorker/PythonRuntime/${distInfoName}`);\n  requireDir(licensesRoot, `LocalWorker/PythonRuntime/${distInfoName}/licenses`);\n  const sourcePath = join(licensesRoot, "TRANSLATEIT_SOURCE.txt");\n  requireFile(sourcePath, `${distInfoName}/licenses/TRANSLATEIT_SOURCE.txt`);\n  if (existsSync(sourcePath)) {\n    const sourceRecord = readFileSync(sourcePath, "utf8");\n    for (const marker of requirement.source) {\n      if (!sourceRecord.includes(marker)) fail(`${distInfoName} exceptional license source marker is missing: ${marker}`);\n    }\n  }\n  for (const [file, expectedHash] of Object.entries(requirement.files)) {\n    const path = join(licensesRoot, file);\n    requireFile(path, `${distInfoName}/licenses/${file}`);\n    if (existsSync(path) && sha256File(path) !== expectedHash) {\n      fail(`${distInfoName} exceptional license material hash mismatch: ${file}`);\n    }\n  }\n}\n\n'''
if anchor not in validator: raise SystemExit('validator notice anchor missing')
if 'exceptional license source marker is missing' not in validator:
    validator=validator.replace(anchor,check+anchor,1)
validator_path.write_text(validator,encoding='utf-8')

contract=contract_path.read_text(encoding='utf-8')
anchor='''for (const marker of [\n  "CPython 3.12.10 Windows embeddable package",\n'''
# Add a separate source-policy check before the existing Python marker loop.
check='''for (const marker of [\n  "Exceptional Frozen-Wheel License Material",\n  "106 of the 116 frozen production distributions",\n  "ctranslate2==4.8.1",\n  "onnxruntime==1.28.0",\n  "sentencepiece==0.2.2",\n  "tensorboard-data-server==0.7.2",\n  "TRANSLATEIT_SOURCE.txt",\n]) {\n  if (!localWorkerReadme.includes(marker)) fail(`Exceptional Python license-material policy marker is missing: ${marker}`);\n}\nfor (const marker of [\n  "const exceptionalPythonLicenseMaterials",\n  "54aa79d9fe3c09e67a16dcd95b9e88676405a6ec174efda31036983cf7672ecb",\n  "0e07b95f3a8d6230037707c5c4a2b554d12c4cb67369669ac255635528ffcee2",\n  "c79a7fea0e3cac04cd43f20e7b648e5a0ff8fa5344e644b0ee09ca1162b62747",\n  "81150b898a306b89cde90e949358c2eefe018eaa",\n  "exceptional license source marker is missing",\n]) {\n  if (!releasePayloadValidator.includes(marker)) fail(`Exceptional Python release validator marker is missing: ${marker}`);\n}\n\n'''
if anchor not in contract: raise SystemExit('package contract Python loop anchor missing')
if 'Exceptional Python license-material policy marker is missing' not in contract:
    contract=contract.replace(anchor,check+anchor,1)
contract_path.write_text(contract,encoding='utf-8')
print('[r3] exceptional frozen-wheel license contract patch applied')
